#!/usr/bin/env python3
"""instanceof/cast Collection para colecciones y vistas modeladas."""
import os,pathlib,subprocess,tempfile
root=pathlib.Path(__file__).resolve().parents[1];jdk=pathlib.Path(os.environ['JAVA_HOME'])/'bin'
source='''package net.minecraft.test;import java.util.*;import java.util.concurrent.*;public class CollectionCastProbe{static class Own implements Collection<Object>{public int size(){return 0;}public boolean isEmpty(){return true;}public boolean contains(Object x){return false;}public Iterator<Object> iterator(){return null;}public Object[] toArray(){return null;}public <T>T[] toArray(T[] a){return null;}public boolean add(Object x){return false;}public boolean remove(Object x){return false;}public boolean containsAll(Collection<?> c){return false;}public boolean addAll(Collection<?> c){return false;}public boolean removeAll(Collection<?> c){return false;}public boolean retainAll(Collection<?> c){return false;}public void clear(){}}public static int run(int n){try{Object x;switch(n%10){case 0:x=null;break;case 1:x=new ArrayList<>();break;case 2:x=new LinkedHashSet<>();break;case 3:x=new HashSet<>();break;case 4:x=new ArrayDeque<>();break;case 5:x=Collections.emptyList();break;case 6:x=new ConcurrentHashMap<String,String>().values();break;case 7:x=new CollectionCastProbe();break;case 8:x=new Own();break;default:x="x";}boolean b=x instanceof Collection;Collection<?> c=(Collection<?>)x;return (b?1:0)+(c==x?2:0);}catch(ClassCastException e){return 9;}}}'''
driver='''import net.minecraft.test.CollectionCastProbe;public class Driver{public static void main(String[]a){for(String n:a)System.out.println(CollectionCastProbe.run(Integer.parseInt(n)));}}'''
with tempfile.TemporaryDirectory(prefix='mc-collection-cast-') as t:
 d=pathlib.Path(t);(d/'CollectionCastProbe.java').write_text(source);(d/'Driver.java').write_text(driver);subprocess.run([str(jdk/'javac'),'-d',str(d),str(d/'CollectionCastProbe.java'),str(d/'Driver.java')],check=True);subprocess.run([str(jdk/'jar'),'cf',str(d/'fixture.jar'),'-C',str(d),'net'],check=True)
 p=subprocess.run(['cargo','run','--quiet','--manifest-path',str(root/'Cargo.toml'),'--','multi-static-demo',str(d/'fixture.jar'),'net/minecraft/test/CollectionCastProbe',str(d/'native'),'run','(I)I'],capture_output=True,text=True,timeout=180)
 if p.returncode:raise RuntimeError(p.stderr)
 seq=list(range(100));j=subprocess.run([str(jdk/'java'),'-cp',str(d),'Driver',*map(str,seq)],capture_output=True,text=True,check=True).stdout;n=subprocess.run([str(d/'native'),*[v for x in seq for v in ('0',str(x))]],capture_output=True,text=True,check=True).stdout
 if j!=n:raise AssertionError((j,n))
 print(f'OK: {len(seq)} resultados Collection/null/list/set/queue/map.values/proyecto e implementación propia')
